/**
 * Netscape cookie-file output, readable by `curl -b <file>` / `curl -c`.
 * Fields (tab separated): domain, includeSubdomains, path, secure, expiry, name, value.
 * HttpOnly cookies carry curl's "#HttpOnly_" domain prefix. Contains live session material.
 */
import type { SessionArtifact } from "../types.js";

export const CURL_JAR_HEADER = "# Netscape HTTP Cookie File";

export function toCurlJar(artifact: SessionArtifact): string {
  const lines = [
    CURL_JAR_HEADER,
    "# Generated by testlane. Live session material: do not commit or share.",
    "",
  ];
  for (const c of artifact.cookies) {
    const domain = `${c.httpOnly ? "#HttpOnly_" : ""}${c.domain}`;
    const includeSubdomains = c.domain.startsWith(".") ? "TRUE" : "FALSE";
    const secure = c.secure ? "TRUE" : "FALSE";
    const expiry = c.expires === -1 ? 0 : Math.floor(c.expires);
    lines.push([domain, includeSubdomains, c.path, secure, String(expiry), c.name, c.value].join("\t"));
  }
  return `${lines.join("\n")}\n`;
}
